-- MOVA initial schema. Execute through Supabase CLI after configuring the project.
create extension if not exists "pgcrypto";
create type public.member_role as enum ('owner','professional','admin');
create type public.subscription_status as enum ('trialing','active','past_due','canceled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(full_name) between 2 and 120), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 2 and 120), created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid references public.organizations(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role public.member_role not null default 'professional', created_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.patients (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), responsible_user_id uuid not null references public.profiles(id), full_name text not null check(char_length(full_name) between 2 and 120), birth_date date, sex text check(sex in ('female','male','other','not_informed')), phone text, notes text check(char_length(notes)<=2000), archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assessments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), patient_id uuid not null references public.patients(id), professional_id uuid not null references public.profiles(id), protocol text not null check(protocol in ('gait_video','walk_10m')), capture_conditions jsonb not null default '{}'::jsonb, manual_duration_seconds numeric check(manual_duration_seconds>0), algorithm_version text, notes text check(char_length(notes)<=2000), status text not null default 'draft' check(status in ('draft','reviewed','final')), created_at timestamptz not null default now());
create table public.assessment_videos (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id) on delete cascade, storage_path text not null, mime_type text not null, byte_size bigint not null check(byte_size > 0 and byte_size <= 524288000), processing_status text not null default 'pending', created_at timestamptz not null default now());
create table public.gait_metrics (id uuid primary key default gen_random_uuid(), assessment_id uuid not null unique references public.assessments(id) on delete cascade, duration_seconds numeric, estimated_steps integer check(estimated_steps>=0), cadence_spm numeric, speed_mps numeric, quality jsonb not null default '{}'::jsonb, limitations text, created_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id), generated_by uuid not null references public.profiles(id), storage_path text not null, generated_at timestamptz not null default now());
create table public.plans (id text primary key, name text not null, features jsonb not null default '{}'::jsonb, active boolean not null default true);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), plan_id text references public.plans(id), status public.subscription_status not null default 'trialing', provider text, provider_subscription_id text unique, current_period_end timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, organization_id uuid references public.organizations(id), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index patients_org_active_idx on public.patients(organization_id, archived_at); create index assessments_patient_created_idx on public.assessments(patient_id, created_at desc); create index audit_logs_org_created_idx on public.audit_logs(organization_id, created_at desc);
create or replace function public.is_member(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members where organization_id=org_id and user_id=auth.uid())$$;
alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.patients enable row level security; alter table public.assessments enable row level security; alter table public.assessment_videos enable row level security; alter table public.gait_metrics enable row level security; alter table public.reports enable row level security; alter table public.subscriptions enable row level security; alter table public.audit_logs enable row level security;
create policy member_orgs on public.organizations for select using(public.is_member(id)); create policy members_read on public.organization_members for select using(public.is_member(organization_id));
create policy patients_org on public.patients for all using(public.is_member(organization_id)) with check(public.is_member(organization_id)); create policy assessments_org on public.assessments for all using(public.is_member(organization_id)) with check(public.is_member(organization_id));
create policy videos_org on public.assessment_videos for all using(exists(select 1 from assessments a where a.id=assessment_id and public.is_member(a.organization_id))) with check(exists(select 1 from assessments a where a.id=assessment_id and public.is_member(a.organization_id)));
create policy metrics_org on public.gait_metrics for select using(exists(select 1 from assessments a where a.id=assessment_id and public.is_member(a.organization_id))); create policy reports_org on public.reports for select using(exists(select 1 from assessments a where a.id=assessment_id and public.is_member(a.organization_id))); create policy subscriptions_org on public.subscriptions for select using(public.is_member(organization_id)); create policy audit_org on public.audit_logs for select using(public.is_member(organization_id));
